from typing import Annotated
from fastapi import FastAPI, Depends, Response
from fastapi.testclient import TestClient
app = FastAPI()
def mod(response: Response):
    response.headers["X-A"] = "1"
    return response
@app.get("/a")
def a(response: Annotated[Response, Depends(mod)]):
    response.headers["X-B"]="2"; return {"ok":1}
@app.get("/b")
def b(response: Response = Depends(mod)):
    return {"ok":1}
@app.get("/c")
def c(response: Response):
    response.headers["X-C"]="3"; return {}
c_ = TestClient(app)
for p in "abc": r=c_.get("/"+p); print(r.status_code, dict(r.headers))
EOF
